const now = new Date();
now.setMinutes(0, 0, 0);
const pad = (value) => String(value).padStart(2, '0');
const tzOffset = -now.getTimezoneOffset();
const sign = tzOffset >= 0 ? '+' : '-';
const absOffset = Math.abs(tzOffset);
const offsetHours = pad(Math.floor(absOffset / 60));
const offsetMinutes = pad(absOffset % 60);
const iso = `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}T${pad(now.getHours())}:${pad(now.getMinutes())}:${pad(now.getSeconds())}${sign}${offsetHours}:${offsetMinutes}`;
const hourLabel = `${pad(now.getHours())}:00`;
const userId = $env.HOURLY_CHECKIN_USER_ID || 'marce';
const token = $env.HOURLY_CHECKIN_TOKEN || 'changeme';
const baseUrl = $env.HOURLY_CHECKIN_FRONTEND || 'https://TU_DOMINIO_FRONT';
const url = `${baseUrl}/checkin?user_id=${encodeURIComponent(userId)}&ts_hour=${encodeURIComponent(iso)}&token=${encodeURIComponent(token)}`;
return [{ json: { ts_hour: iso, message: `Check-in de las ${hourLabel}
${url}`, url, user_id: userId } }];
